"""A minimal threaded HTTP server for the sandbox fabric (proxies and mock services).

Every proxy in front of a sandboxed host (LLM metering, chaos, egress) is one of these, so the
request/response shape is shared and each component stays a plain function that tests can call
without sockets. Responses may stream (the LLM proxy relays server-sent events).
"""

from __future__ import annotations

import json
import threading
from collections.abc import Callable, Iterable, Mapping
from dataclasses import dataclass, field
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from types import TracebackType
from typing import Any
from urllib.parse import parse_qsl, urlsplit

TASK_HEADER = "x-kintsugi-task"  # correlates a host's external calls with its task (chaos, cassettes)


@dataclass(frozen=True)
class HttpRequest:
    method: str
    path: str
    query: Mapping[str, str]
    headers: Mapping[str, str]  # lower-cased names
    body: bytes = b""

    @property
    def task(self) -> str:
        return self.headers.get(TASK_HEADER, "")

    def json(self) -> Any:
        return json.loads(self.body.decode("utf-8")) if self.body else None


@dataclass
class HttpResponse:
    status: int
    headers: dict[str, str] = field(default_factory=dict)
    body: bytes = b""
    stream: Iterable[bytes] | None = None  # sent chunk by chunk when set; ``body`` is ignored

    @classmethod
    def of_json(cls, status: int, value: Any, headers: Mapping[str, str] | None = None) -> HttpResponse:
        merged = {"content-type": "application/json", **(headers or {})}
        return cls(status, merged, json.dumps(value, ensure_ascii=False).encode("utf-8"))

    def json(self) -> Any:
        return json.loads(self.body.decode("utf-8")) if self.body else None


Handler = Callable[[HttpRequest], HttpResponse]

_HOP_BY_HOP = frozenset(
    {"connection", "keep-alive", "transfer-encoding", "te", "trailer", "upgrade",
     "proxy-authorization", "proxy-authenticate", "content-length", "host"}
)  # fmt: skip


def forwardable(headers: Mapping[str, str]) -> dict[str, str]:
    """Drop hop-by-hop headers before relaying a request or response."""
    return {k: v for k, v in headers.items() if k.lower() not in _HOP_BY_HOP}


def _make_handler_class(handler: Handler) -> type[BaseHTTPRequestHandler]:
    class _Adapter(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def _dispatch(self) -> None:
            split = urlsplit(self.path)
            length = int(self.headers.get("content-length") or 0)
            body = self.rfile.read(length) if length else b""
            request = HttpRequest(
                method=self.command,
                path=split.path,
                query=dict(parse_qsl(split.query, keep_blank_values=True)),
                headers={k.lower(): v for k, v in self.headers.items()},
                body=body,
            )
            try:
                response = handler(request)
            except Exception as error:  # a handler bug must not hang the client
                response = HttpResponse.of_json(
                    500, {"type": "error", "error": {"type": "proxy_error", "message": str(error)}}
                )
            self._send(response)

        def _send(self, response: HttpResponse) -> None:
            self.send_response(response.status)
            for name, value in forwardable(response.headers).items():
                self.send_header(name, value)
            if response.stream is None:
                self.send_header("content-length", str(len(response.body)))
                self.end_headers()
                self.wfile.write(response.body)
                return
            self.send_header("transfer-encoding", "chunked")
            self.end_headers()
            for chunk in response.stream:
                if chunk:
                    self.wfile.write(b"%x\r\n%s\r\n" % (len(chunk), chunk))
                    self.wfile.flush()
            self.wfile.write(b"0\r\n\r\n")

        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = _dispatch

        def log_message(self, format: str, *args: Any) -> None:  # noqa: A002 - stdlib signature
            return  # quiet: the proxies keep their own structured records

    return _Adapter


class Server:
    """Serve ``handler`` on ``host:port`` (0 = ephemeral) in a daemon thread."""

    def __init__(self, handler: Handler, *, host: str = "127.0.0.1", port: int = 0) -> None:
        self._httpd = ThreadingHTTPServer((host, port), _make_handler_class(handler))
        self._httpd.daemon_threads = True
        self._thread = threading.Thread(target=self._httpd.serve_forever, daemon=True)

    @property
    def url(self) -> str:
        host, port = self._httpd.server_address[:2]
        return f"http://{host!s}:{port}"

    def start(self) -> Server:
        self._thread.start()
        return self

    def stop(self) -> None:
        self._httpd.shutdown()
        self._httpd.server_close()

    def __enter__(self) -> Server:
        return self.start()

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        self.stop()

"""Cassettes: record and replay a host's external I/O (spec §5.11 G0/G2, §6.2 step 7).

A cassette holds every exchange a task had with the outside world (the FX API, the document
store, the mock GitHub, the model) **including injected faults at their original position**, so
a replay reproduces the failure deterministically. Exchanges are keyed by

    (service, task, fingerprint(request), occurrence)

where ``occurrence`` counts identical requests within one task. A retry after a 429 is the same
request seen a second time, so it replays the second recorded answer, not the first.

Secrets never enter a cassette: only an allowlist of response headers is kept and request
headers are not recorded at all. The cassette's identity is the SHA-256 of its canonical form
(the ``reproduce`` activity's idempotency key is ``(incident, cassette_sha)``, spec §5.3.2).
"""

from __future__ import annotations

import json
import threading
from collections import Counter
from collections.abc import Mapping
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml

from kintsugi.proof.canonical import canonicalize, digest, sha256_hex
from kintsugi.sandbox.httpserve import HttpRequest, HttpResponse

FORMAT = "kintsugi.cassette/v1"
KEPT_RESPONSE_HEADERS = frozenset({"content-type", "retry-after", "x-kintsugi-chaos"})


class CassetteMiss(LookupError):
    """A replayed task made a request the cassette never saw (or saw fewer times)."""


def _body_value(body: bytes) -> Any:
    """JSON bodies are stored parsed (stable under key order and whitespace); others as text."""
    if not body:
        return None
    text = body.decode("utf-8", errors="replace")
    try:
        return json.loads(text)
    except ValueError:
        return text


def request_record(request: HttpRequest, *, path: str | None = None) -> dict[str, Any]:
    return {
        "method": request.method,
        "path": path if path is not None else request.path,
        "query": dict(sorted(request.query.items())),
        "body": _body_value(request.body),
    }


def fingerprint(record: Mapping[str, Any]) -> str:
    return sha256_hex(canonicalize(dict(record)))


def response_record(response: HttpResponse) -> dict[str, Any]:
    headers = {k.lower(): v for k, v in response.headers.items()}
    return {
        "status": response.status,
        "headers": {k: v for k, v in sorted(headers.items()) if k in KEPT_RESPONSE_HEADERS},
        "body": _body_value(response.body),
    }


def to_response(record: Mapping[str, Any]) -> HttpResponse:
    body = record.get("body")
    if body is None:
        raw = b""
    elif isinstance(body, str):
        raw = body.encode("utf-8")
    else:
        raw = json.dumps(body, ensure_ascii=False).encode("utf-8")
    return HttpResponse(int(record["status"]), dict(record.get("headers") or {}), raw)


@dataclass(frozen=True)
class Exchange:
    service: str
    task: str
    key: str
    occurrence: int
    request: dict[str, Any]
    response: dict[str, Any]
    latency_ms: int = 0

    def as_dict(self) -> dict[str, Any]:
        return {
            "service": self.service, "task": self.task, "key": self.key,
            "occurrence": self.occurrence, "request": self.request,
            "response": self.response, "latency_ms": self.latency_ms,
        }  # fmt: skip


@dataclass
class Cassette:
    name: str
    exchanges: list[Exchange] = field(default_factory=list)
    meta: dict[str, Any] = field(default_factory=dict)

    def as_dict(self) -> dict[str, Any]:
        return {
            "format": FORMAT,
            "name": self.name,
            "meta": self.meta,
            "exchanges": [e.as_dict() for e in self.exchanges],
        }

    @property
    def sha256(self) -> str:
        return digest(self.as_dict())

    def tasks(self) -> list[str]:
        return sorted({e.task for e in self.exchanges})

    def save(self, path: Path) -> Path:
        path.parent.mkdir(parents=True, exist_ok=True)
        data = self.as_dict()
        if path.suffix in {".yaml", ".yml"}:
            text = yaml.safe_dump(data, sort_keys=False, allow_unicode=True)
        else:
            text = json.dumps(data, ensure_ascii=False, indent=1) + "\n"
        path.write_text(text, encoding="utf-8", newline="\n")
        return path

    @classmethod
    def load(cls, path: Path) -> Cassette:
        text = path.read_text(encoding="utf-8")
        data = yaml.safe_load(text) if path.suffix in {".yaml", ".yml"} else json.loads(text)
        return cls.from_dict(data)

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> Cassette:
        if data.get("format") != FORMAT:
            raise ValueError(f"not a {FORMAT} cassette: {data.get('format')!r}")
        exchanges = [
            Exchange(
                service=e["service"], task=e["task"], key=e["key"],
                occurrence=int(e["occurrence"]), request=e["request"],
                response=e["response"], latency_ms=int(e.get("latency_ms", 0)),
            )
            for e in data["exchanges"]
        ]  # fmt: skip
        return cls(name=data["name"], exchanges=exchanges, meta=dict(data.get("meta") or {}))


class Recorder:
    """Thread-safe: concurrent tasks append exchanges; occurrence is counted per task."""

    def __init__(self, name: str, meta: Mapping[str, Any] | None = None) -> None:
        self._cassette = Cassette(name, meta=dict(meta or {}))
        self._seen: Counter[tuple[str, str, str]] = Counter()
        self._lock = threading.Lock()

    def record(
        self, service: str, task: str, request: dict[str, Any], response: dict[str, Any],
        latency_ms: int = 0,
    ) -> Exchange:  # fmt: skip
        key = fingerprint(request)
        with self._lock:
            occurrence = self._seen[(service, task, key)]
            self._seen[(service, task, key)] += 1
            exchange = Exchange(service, task, key, occurrence, request, response, latency_ms)
            self._cassette.exchanges.append(exchange)
        return exchange

    def occurrence(self, service: str, task: str, key: str) -> int:
        """How many times this request has been recorded for the task so far."""
        with self._lock:
            return self._seen[(service, task, key)]

    def cassette(self) -> Cassette:
        with self._lock:
            ordered = sorted(
                self._cassette.exchanges, key=lambda e: (e.task, e.service, e.key, e.occurrence)
            )
            return Cassette(self._cassette.name, list(ordered), dict(self._cassette.meta))


class Player:
    """Serves recorded responses in occurrence order; a miss is an error, never a live call."""

    def __init__(self, cassette: Cassette, *, task_map: Mapping[str, str] | None = None) -> None:
        self._index = {(e.service, e.task, e.key, e.occurrence): e for e in cassette.exchanges}
        self._next: Counter[tuple[str, str, str]] = Counter()
        self._task_map = dict(task_map or {})  # replay task id → recorded task id
        self._lock = threading.Lock()
        self.cassette = cassette

    def play(self, service: str, task: str, request: dict[str, Any]) -> Exchange:
        recorded_task = self._task_map.get(task, task)
        key = fingerprint(request)
        with self._lock:
            n = self._next[(service, recorded_task, key)]
            exchange = self._index.get((service, recorded_task, key, n))
            if exchange is None:
                raise CassetteMiss(
                    f"{service} {request['method']} {request['path']} (task {recorded_task!r}, "
                    f"occurrence {n}) is not in cassette {self.cassette.name!r}"
                )
            self._next[(service, recorded_task, key)] += 1
        return exchange

    def unplayed(self) -> list[Exchange]:
        with self._lock:
            return [
                e for (s, t, k, n), e in self._index.items() if n >= self._next[(s, t, k)]
            ]

"""The seeded chaos proxy in front of every host's "external" services (spec §5.10, App. B).

Every tool call a host makes to an external service (the FX API, the document store, the mock
GitHub) goes through ``/{service}/{path}`` on this proxy. Faults are drawn from a profile:

- ``status``: answer with an HTTP error (e.g. 429) **without** calling the upstream, so a faulted
  call to a side-effecting service has no side effect;
- ``latency``: add a uniform delay;
- ``schema_drift``: rename fields in a JSON response;
- ``partial``: truncate a JSON list (or a text body) to a fraction.

Determinism: whether rule *r* fires on a call is ``u < rate`` with

    u = HMAC-SHA256(seed, r ‖ service ‖ task ‖ fingerprint(request) ‖ occurrence) / 2^64

so the same seed produces the same faults at the same positions on every run, independent of
thread scheduling: concurrent tasks never share an occurrence counter (calls carry their task
id in ``x-kintsugi-task``). The background profile (`profiles/background.yaml`) is disclosed;
sabotage profiles are sealed by the Saboteur (Stage 8).
"""

from __future__ import annotations

import fnmatch
import hashlib
import hmac
import json
import threading
import time
from collections import Counter
from collections.abc import Callable, Mapping
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Literal

import httpx
import yaml

from kintsugi.sandbox.cassette import (
    Player,
    Recorder,
    fingerprint,
    request_record,
    response_record,
    to_response,
)
from kintsugi.sandbox.httpserve import Handler, HttpRequest, HttpResponse, forwardable

PROFILES = Path(__file__).with_name("profiles")
CHAOS_HEADER = "x-kintsugi-chaos"
FaultKind = Literal["status", "latency", "schema_drift", "partial"]


@dataclass(frozen=True)
class Rule:
    service: str  # glob over service names
    fault: FaultKind
    rate: float
    path: str = "*"  # glob over the path inside the service
    params: Mapping[str, Any] = field(default_factory=dict)

    def applies(self, service: str, path: str) -> bool:
        return fnmatch.fnmatchcase(service, self.service) and fnmatch.fnmatchcase(path, self.path)


@dataclass(frozen=True)
class Profile:
    name: str
    seed: int
    rules: tuple[Rule, ...]
    disclosed: bool = True

    def with_seed(self, seed: int) -> Profile:
        return Profile(self.name, seed, self.rules, self.disclosed)


def load_profile(path: Path) -> Profile:
    data = yaml.safe_load(path.read_text(encoding="utf-8"))
    rules = []
    for raw in data.get("rules") or []:
        raw = dict(raw)
        service, fault, rate = raw.pop("service"), raw.pop("fault"), float(raw.pop("rate"))
        if fault not in {"status", "latency", "schema_drift", "partial"}:
            raise ValueError(f"unknown fault kind {fault!r}")
        if not 0.0 <= rate <= 1.0:
            raise ValueError(f"rate must be within [0, 1], got {rate}")
        rules.append(Rule(service, fault, rate, str(raw.pop("path", "*")), raw))
    return Profile(str(data["name"]), int(data.get("seed", 0)), tuple(rules),
                   bool(data.get("disclosed", True)))  # fmt: skip


def background_profile() -> Profile:
    return load_profile(PROFILES / "background.yaml")


def unit(seed: int, *parts: object) -> float:
    """A deterministic uniform draw in [0, 1) from the seed and the call's coordinates."""
    message = "\x1f".join(str(p) for p in parts).encode("utf-8")
    mac = hmac.new(str(seed).encode("ascii"), message, hashlib.sha256).digest()
    return int.from_bytes(mac[:8], "big") / 2**64


@dataclass(frozen=True)
class Decision:
    rule: int
    fault: FaultKind
    params: Mapping[str, Any]
    draw: float  # the uniform draw that fired (or set the latency)


def decide(
    profile: Profile, service: str, path: str, task: str, key: str, occurrence: int
) -> list[Decision]:
    fired: list[Decision] = []
    for index, rule in enumerate(profile.rules):
        if not rule.applies(service, path):
            continue
        u = unit(profile.seed, index, service, task, key, occurrence)
        if u < rule.rate:
            jitter = unit(profile.seed, "jitter", index, service, task, key, occurrence)
            fired.append(Decision(index, rule.fault, rule.params, jitter))
    return fired


def _error_body(status: int) -> dict[str, Any]:
    kinds = {429: "rate_limit_error", 500: "api_error", 502: "bad_gateway", 503: "overloaded"}
    return {"type": "error", "error": {"type": kinds.get(status, "upstream_error"),
                                       "message": f"chaos: injected HTTP {status}"}}  # fmt: skip


def _rename(value: Any, renames: Mapping[str, str]) -> Any:
    if isinstance(value, dict):
        return {renames.get(k, k): _rename(v, renames) for k, v in value.items()}
    if isinstance(value, list):
        return [_rename(v, renames) for v in value]
    return value


def _truncate(value: Any, field_name: str | None, keep: float) -> Any:
    if field_name is None:
        if isinstance(value, list):
            return value[: int(len(value) * keep)]
        if isinstance(value, str):
            return value[: int(len(value) * keep)]
        return value
    if isinstance(value, dict) and isinstance(value.get(field_name), list | str):
        return {**value, field_name: _truncate(value[field_name], None, keep)}
    return value


def apply_body_faults(response: HttpResponse, decisions: list[Decision]) -> HttpResponse:
    """Apply schema-drift and partial-response faults to a JSON (or text) upstream response."""
    shaping = [d for d in decisions if d.fault in {"schema_drift", "partial"}]
    if not shaping or not response.body:
        return response
    try:
        body: Any = json.loads(response.body.decode("utf-8"))
        is_json = True
    except ValueError:
        body, is_json = response.body.decode("utf-8", errors="replace"), False
    for d in shaping:
        if d.fault == "schema_drift":
            body = _rename(body, dict(d.params.get("rename") or {}))
        else:
            body = _truncate(body, d.params.get("field"), float(d.params.get("keep", 0.5)))
    raw = json.dumps(body, ensure_ascii=False).encode("utf-8") if is_json else str(body).encode()
    return HttpResponse(response.status, dict(response.headers), raw)


Upstream = str | Handler  # a base URL, or an in-process handler (mock services, tests)


class ChaosProxy:
    """``/{service}/{path}`` → the service's upstream, with seeded faults; record or replay."""

    def __init__(
        self,
        upstreams: Mapping[str, Upstream],
        profile: Profile,
        *,
        recorder: Recorder | None = None,
        player: Player | None = None,
        sleep: Callable[[float], None] = time.sleep,
        timeout_s: float = 30.0,
    ) -> None:
        if recorder is not None and player is not None:
            raise ValueError("record or replay, not both")
        self.upstreams = dict(upstreams)
        self.profile = profile
        self.recorder = recorder
        self.player = player
        self._sleep = sleep
        self._seen: Counter[tuple[str, str, str]] = Counter()
        self._lock = threading.Lock()
        self._client = httpx.Client(timeout=timeout_s)
        self.log: list[dict[str, Any]] = []  # one row per call: what fired where

    def __call__(self, request: HttpRequest) -> HttpResponse:
        service, _, rest = request.path.lstrip("/").partition("/")
        path = "/" + rest
        if service not in self.upstreams:
            return HttpResponse.of_json(404, _error_body(404) | {"service": service})
        record = request_record(request, path=path)
        if self.player is not None:  # replay: the recorded answer, faults included
            return to_response(self.player.play(service, request.task, record).response)

        key = fingerprint(record)
        with self._lock:
            occurrence = self._seen[(service, request.task, key)]
            self._seen[(service, request.task, key)] += 1
        decisions = decide(self.profile, service, path, request.task, key, occurrence)
        started = time.monotonic()
        for d in decisions:
            if d.fault == "latency":
                low, high = (d.params.get("latency_ms") or [0, 0])[:2]
                self._sleep((low + (high - low) * d.draw) / 1000.0)
        status_fault = next((d for d in decisions if d.fault == "status"), None)
        if status_fault is not None:
            status = int(status_fault.params.get("status", 429))
            headers = {"retry-after": str(status_fault.params.get("retry_after_s", 0))}
            response = HttpResponse.of_json(status, _error_body(status), headers)
        else:
            response = apply_body_faults(self._forward(service, path, request), decisions)
        fired = ",".join(f"{d.fault}#{d.rule}" for d in decisions)
        if fired:
            response.headers[CHAOS_HEADER] = fired
        latency_ms = int((time.monotonic() - started) * 1000)
        self.log.append({"service": service, "path": path, "task": request.task,
                         "occurrence": occurrence, "status": response.status, "fired": fired})  # fmt: skip
        if self.recorder is not None:
            self.recorder.record(service, request.task, record, response_record(response),
                                 latency_ms)  # fmt: skip
        return response

    def _forward(self, service: str, path: str, request: HttpRequest) -> HttpResponse:
        upstream = self.upstreams[service]
        inner = HttpRequest(request.method, path, request.query, request.headers, request.body)
        if callable(upstream):
            return upstream(inner)
        reply = self._client.request(
            request.method, upstream.rstrip("/") + path, params=dict(request.query),
            content=request.body, headers=forwardable(request.headers),
        )  # fmt: skip
        return HttpResponse(reply.status_code, dict(reply.headers), reply.content)

    def close(self) -> None:
        self._client.close()

