"""Reconciliation: post a document's draft lines in USD, exactly once each.

A document becomes a ``Batch`` of draft lines in its own currency plus one USD balancing line
(accounts payable for invoices and credit notes, cash for payments). ``run_reconcile`` converts
and posts the lines through ``fx_rate``, which an external API serves and may rate-limit; a 429
re-runs the whole attempt. The ``ReconcileSession`` remembers which lines are already posted
and where to resume, so a retry never books a line twice.
"""

from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

from ledger.db import JournalLine, LedgerDB
from ledger.tools import ParsedDocument, fx_rate, post_journal_entry
from ledger.util.retry import RateLimited, retry_with_backoff
from ledger.vendors import CASH, FREIGHT, INPUT_TAX, PAYABLE, Vendor

CENT = Decimal("0.01")


class IncompleteDocument(ValueError):
    reason_code = "INCOMPLETE_DOCUMENT"


@dataclass(frozen=True)
class DraftLine:
    key: str
    account: str
    amount: Decimal  # document currency; debit positive, credit negative
    currency: str
    date: str


@dataclass(frozen=True)
class Batch:
    ref: str
    date: str
    lines: tuple[DraftLine, ...]
    balance_account: str  # receives the USD balancing line


def build_batch(doc: ParsedDocument, vendor: Vendor) -> Batch:
    ref, currency, date = doc.reference, doc.currency, doc.date
    if doc.doc_type == "payment":
        if doc.amount_paid is None:
            raise IncompleteDocument(f"{ref}: a payment without an amount")
        paid = DraftLine(f"{ref}#1", PAYABLE, doc.amount_paid, currency, date)
        return Batch(ref, date, (paid,), CASH)
    sign = Decimal(-1) if doc.doc_type == "credit_note" else Decimal(1)
    drafts = [
        DraftLine(f"{ref}#{n}", FREIGHT if line.kind == "shipping" else vendor.expense_account,
                  sign * line.amount, currency, date)
        for n, line in enumerate(doc.lines, 1)
    ]  # fmt: skip
    if doc.tax:
        drafts.append(DraftLine(f"{ref}#tax", INPUT_TAX, sign * doc.tax, currency, date))
    return Batch(ref, date, tuple(drafts), PAYABLE)


class ReconcileSession:
    """Posted-line memory and the resume cursor for one batch."""

    def __init__(self, batch: Batch) -> None:
        self.batch = batch
        self.posted: set[str] = set()
        self.cursor = 0
        self.total = Decimal(0)

    @property
    def balance_key(self) -> str:
        return f"{self.batch.ref}#bal"

    @property
    def done(self) -> bool:
        return self.balance_key in self.posted

    def pending(self) -> tuple[DraftLine, ...]:
        return self.batch.lines[self.cursor :]

    def post(self, db: LedgerDB, line: DraftLine, rate: Decimal) -> None:
        if line.key not in self.posted:
            amount = (line.amount * rate).quantize(CENT, rounding=ROUND_HALF_UP)
            post_journal_entry(db, JournalLine(line.key, self.batch.ref, line.account, amount,
                                               line.date))  # fmt: skip
            self.posted.add(line.key)
            self.total += amount
        self.cursor += 1

    def close(self, db: LedgerDB) -> None:
        if not self.done:
            post_journal_entry(db, JournalLine(self.balance_key, self.batch.ref,
                                               self.batch.balance_account, -self.total,
                                               self.batch.date))  # fmt: skip
            self.posted.add(self.balance_key)


def run_reconcile(
    db: LedgerDB, batch: Batch, session: ReconcileSession | None = None
) -> ReconcileSession:
    session = session or ReconcileSession(batch)  # outside the retried scope: survives retries

    def attempt() -> ReconcileSession:
        for line in session.pending():
            rate = fx_rate(line.currency, line.date)
            session.post(db, line, rate)
        session.close(db)
        return session

    return retry_with_backoff(attempt)


def process_invoice(db: LedgerDB, batch: Batch) -> ReconcileSession:
    return run_reconcile(db, batch)


def batch_worker(
    db: LedgerDB, batches: Iterable[Batch], sessions: dict[str, ReconcileSession] | None = None
) -> dict[str, ReconcileSession]:
    """Reconcile a queue of batches. A batch still rate-limited after its retries keeps its
    session, so the next pass resumes it where it stopped instead of starting over."""
    sessions = {} if sessions is None else sessions
    for batch in batches:
        session = sessions.setdefault(batch.ref, ReconcileSession(batch))
        if session.done:
            continue
        try:
            run_reconcile(db, batch, session)
        except RateLimited:
            continue  # resumed on the next pass
    return sessions

"""Render synthetic vendor documents as text, in each vendor's local conventions."""

from __future__ import annotations

import datetime as dt
from dataclasses import dataclass
from decimal import Decimal

from ledger.vendors import Vendor

ADDRESSES = {
    "US": "1200 Market Street, Suite 400, Springfield, IL 62701, USA",
    "DE": "Friedrichstrasse 88, 10117 Berlin, Germany",
    "GB": "14 Dockside Way, Felixstowe IP11 3SY, United Kingdom",
    "JP": "3-7-1 Nishi-Shinjuku, Shinjuku-ku, Tokyo 163-1430, Japan",
    "IN": "Tower B, 9th Floor, Cyber City, Gurugram 122002, India",
    "CA": "220 King Street West, Toronto, ON M5H 1K4, Canada",
    "FR": "27 rue du Faubourg Saint-Antoine, 75011 Paris, France",
}
TAX_LABELS = {"DE": "MwSt.", "GB": "VAT", "FR": "TVA", "IN": "GST", "JP": "Consumption tax",
              "CA": "GST"}  # fmt: skip
LINES_PER_PAGE = 4


@dataclass(frozen=True)
class Line:
    description: str
    qty: int
    unit: Decimal
    kind: str  # "item" or "shipping"

    @property
    def amount(self) -> Decimal:
        return self.unit * self.qty


@dataclass(frozen=True)
class Document:
    doc_type: str
    vendor: Vendor
    reference: str
    date: str  # ISO
    lines: tuple[Line, ...] = ()
    tax: Decimal = Decimal(0)
    applies_to: str | None = None
    invoice_total: Decimal | None = None  # payments: the invoice being paid
    amount_paid: Decimal | None = None

    @property
    def subtotal(self) -> Decimal:
        return sum((line.amount for line in self.lines), Decimal(0))

    @property
    def total(self) -> Decimal:
        if self.doc_type == "payment":
            assert self.invoice_total is not None
            return self.invoice_total
        return self.subtotal + self.tax


def money(amount: Decimal, vendor: Vendor) -> str:
    """An amount in the vendor's local number format."""
    if vendor.currency == "JPY":
        return f"{amount:,.0f}"
    plain = f"{amount:,.2f}"  # 1,234,567.89
    if vendor.country == "DE":
        return plain.replace(",", "_").replace(".", ",").replace("_", ".")
    if vendor.country == "FR":
        return plain.replace(",", " ").replace(".", ",")
    if vendor.country == "IN":
        whole, cents = f"{amount:.2f}".split(".")
        sign = "-" if whole.startswith("-") else ""
        whole = whole.lstrip("-")
        head, tail = whole[:-3], whole[-3:]
        groups = []
        while len(head) > 2:
            groups.insert(0, head[-2:])
            head = head[:-2]
        if head:
            groups.insert(0, head)
        return sign + ",".join([*groups, tail]) + "." + cents
    return plain


def local_date(iso: str, vendor: Vendor) -> str:
    day = dt.date.fromisoformat(iso)
    if vendor.country == "US":
        return day.strftime("%b ") + f"{day.day}, {day.year}"
    if vendor.country == "DE":
        return day.strftime("%d.%m.%Y")
    if vendor.country in {"GB", "FR"}:
        return day.strftime("%d/%m/%Y")
    if vendor.country == "IN":
        return day.strftime("%d-%m-%Y")
    return iso


def _header(doc: Document, title: str, number_label: str) -> list[str]:
    v = doc.vendor
    rows = [v.name, ADDRESSES[v.country], "", title, f"{number_label}: {doc.reference}",
            f"Date: {local_date(doc.date, v)}", f"Currency: {v.currency}",
            "Bill to: Kintsugi Demo Co. - Accounts Payable"]  # fmt: skip
    if doc.applies_to:
        rows.append(f"Applies to invoice: {doc.applies_to}")
    return rows


def _table(lines: tuple[Line, ...], vendor: Vendor) -> list[str]:
    return [f"{line.description} | {line.qty} | {money(line.unit, vendor)} | "
            f"{money(line.amount, vendor)}" for line in lines]  # fmt: skip


def render(doc: Document) -> str:
    v = doc.vendor
    if doc.doc_type == "payment":
        assert doc.amount_paid is not None and doc.invoice_total is not None
        rows = _header(doc, "PAYMENT RECEIPT - received with thanks", "Payment ref")
        rows += ["", f"Invoice total: {money(doc.invoice_total, v)}",
                 f"Amount paid: {money(doc.amount_paid, v)}",
                 f"Balance remaining: {money(doc.invoice_total - doc.amount_paid, v)}"]  # fmt: skip
        return "\n".join(rows) + "\n"
    credit = doc.doc_type == "credit_note"
    rows = _header(doc, "CREDIT NOTE" if credit else "TAX INVOICE",
                   "Credit note no" if credit else "Invoice no")  # fmt: skip
    pages = [doc.lines[i : i + LINES_PER_PAGE] for i in range(0, len(doc.lines), LINES_PER_PAGE)]
    head = "Description | Qty | Unit price | Amount"
    for number, page in enumerate(pages, 1):
        if number > 1:
            rows += ["", f"--- Page {number} of {len(pages)} ---",
                     f"{v.name} | {doc.reference} (continued)"]  # fmt: skip
        rows += ["", head, *_table(page, v)]
        if number < len(pages):
            page_total = sum((line.amount for line in page), Decimal(0))
            rows += [f"Page subtotal: {money(page_total, v)}",
                     f"Page {number} of {len(pages)} - continued on next page"]  # fmt: skip
    rows += ["", f"Subtotal: {money(doc.subtotal, v)}"]
    if doc.tax:
        rate = Decimal(v.tax_rate) * 100
        rows.append(f"{TAX_LABELS[v.country]} {rate:.0f}%: {money(doc.tax, v)}")
    rows.append(f"{'Total credit' if credit else 'Total due'}: {money(doc.total, v)}")
    if len(pages) > 1:
        rows.append(f"Page {len(pages)} of {len(pages)}")
    rows += ["", "Payment terms: Net 30. Please quote the document number with any payment."]
    return "\n".join(rows) + "\n"

"""Seeded synthetic vendor documents with gold journal lines (spec §5.9.1: 120 tasks, 80/40).

The train split is generated from a public seed. The holdout is generated from a **secret**
seed by Omega's ``kintsugi holdout seal`` and stored age-encrypted, so it cannot be regenerated
from this file. Live traffic uses run-specific seeds (``live-<seed>``).

The gold journal is computed here independently of Ledger's own posting code: one USD line per
document line (tax included), each converted at the FX API's rate and rounded half-up to the
cent, plus a balancing line to accounts payable (invoices, credit notes) or cash (payments).
"""

from __future__ import annotations

import random
from decimal import ROUND_HALF_UP, Decimal
from typing import Any

from ledger.evals.documents import Document, Line, render
from ledger.services import fx_api
from ledger.vendors import CASH, FREIGHT, INPUT_TAX, PAYABLE, VENDORS, Vendor

TRAIN_SEED = 20261011
SIZES = {"train": 80, "holdout": 40}
CENT = Decimal("0.01")

ITEMS: dict[str, tuple[str, ...]] = {
    "V-1001": ("Copy paper A4, 10 reams", "Toner cartridge, black", "Desk organiser set",
               "Whiteboard markers, 12-pack", "Ergonomic chair mat"),
    "V-1002": ("Cloud compute, monthly", "Managed database, monthly", "Object storage, 5 TB",
               "Support plan, business tier", "Data egress overage"),
    "V-1003": ("Ocean freight, FEU container", "Customs clearance", "Drayage, port to warehouse",
               "Warehouse handling", "Fuel surcharge"),
    "V-1004": ("Stepper motor NEMA 17", "Hall-effect sensor module", "Aluminium heat sink",
               "Connector harness, 24-pin", "Precision bearing kit"),
    "V-1005": ("Advisory retainer, monthly", "Process audit, fixed fee", "Tax filing support",
               "Workshop facilitation", "Travel expenses, reimbursable"),
    "V-1006": ("Office rent, monthly", "Common area maintenance", "Cleaning services",
               "HVAC servicing", "Security patrol"),
    "V-1007": ("Campaign management fee", "Paid social media spend", "Creative production",
               "Event booth design", "Market research report"),
    "V-1008": ("Business fibre 1 Gbps", "Mobile plan, 25 lines", "SIP trunk, 30 channels",
               "Number porting fee", "Roaming charges"),
}  # fmt: skip
GOODS = {"V-1001", "V-1004"}
SHIPPING = ("Shipping and handling", "Freight, ground delivery", "Express delivery charge")


def _unit(rng: random.Random, vendor: Vendor) -> Decimal:
    if vendor.currency == "JPY":
        return Decimal(rng.randrange(800, 90_000, 10))
    if vendor.currency == "INR":
        return Decimal(rng.randrange(150_000, 9_000_000)) / 100
    return Decimal(rng.randrange(1_500, 400_000)) / 100


def _round(amount: Decimal, vendor: Vendor) -> Decimal:
    step = Decimal(1) if vendor.currency == "JPY" else CENT
    return amount.quantize(step, rounding=ROUND_HALF_UP)


def _date(rng: random.Random) -> str:
    month, day = rng.choice((7, 8, 9)), rng.randrange(1, 29)
    return f"2026-{month:02d}-{day:02d}"


def _invoice(rng: random.Random, vendor: Vendor, ref: str, *, long: bool) -> Document:
    count = rng.randrange(5, 11) if long else rng.randrange(1, 5)
    lines = [Line(rng.choice(ITEMS[vendor.id]), rng.randrange(1, 6), _unit(rng, vendor), "item")
             for _ in range(count)]  # fmt: skip
    if vendor.id in GOODS and rng.random() < 0.5:
        lines.append(Line(rng.choice(SHIPPING), 1, _round(_unit(rng, vendor) / 4, vendor),
                          "shipping"))  # fmt: skip
    subtotal = sum((line.amount for line in lines), Decimal(0))
    tax = _round(subtotal * Decimal(vendor.tax_rate), vendor)
    return Document("invoice", vendor, ref, _date(rng), tuple(lines), tax)


def _credit_note(rng: random.Random, vendor: Vendor, ref: str, invoice: str) -> Document:
    lines = [Line(f"Credit: {rng.choice(ITEMS[vendor.id]).lower()}", rng.randrange(1, 3),
                  _round(_unit(rng, vendor) / 3, vendor), "item")
             for _ in range(rng.randrange(1, 3))]  # fmt: skip
    subtotal = sum((line.amount for line in lines), Decimal(0))
    tax = _round(subtotal * Decimal(vendor.tax_rate), vendor)
    return Document("credit_note", vendor, ref, _date(rng), tuple(lines), tax, applies_to=invoice)


def _payment(rng: random.Random, vendor: Vendor, ref: str, invoice: Document) -> Document:
    paid = _round(invoice.total * Decimal(rng.randrange(35, 81)) / 100, vendor)
    return Document("payment", vendor, ref, _date(rng), applies_to=invoice.reference,
                    invoice_total=invoice.total, amount_paid=paid)  # fmt: skip


def gold_lines(doc: Document) -> list[dict[str, Any]]:
    rate = fx_api.rate(doc.vendor.currency, doc.date)

    def usd(amount: Decimal) -> Decimal:
        return (amount * rate).quantize(CENT, rounding=ROUND_HALF_UP)

    if doc.doc_type == "payment":
        assert doc.amount_paid is not None
        drafts = [(PAYABLE, usd(doc.amount_paid))]
        balance = CASH
    else:
        sign = -1 if doc.doc_type == "credit_note" else 1
        drafts = [(FREIGHT if line.kind == "shipping" else doc.vendor.expense_account,
                   sign * usd(line.amount)) for line in doc.lines]  # fmt: skip
        if doc.tax:
            drafts.append((INPUT_TAX, sign * usd(doc.tax)))
        balance = PAYABLE
    drafts.append((balance, -sum((amount for _, amount in drafts), Decimal(0))))
    return [{"account": account, "amount_cents": int(amount * 100), "currency": "USD",
             "date": doc.date} for account, amount in drafts]  # fmt: skip


def generate(split: str, seed: int, n: int) -> list[dict[str, Any]]:
    rng = random.Random(f"ledger:{split}:{seed}")
    issued: list[Document] = []
    tasks = []
    for i in range(n):
        vendor = rng.choice(VENDORS)
        number = rng.randrange(10_000, 99_999)
        roll = rng.random()
        prior = [d for d in issued if d.vendor == vendor]
        if roll < 0.20 and prior:
            doc = _credit_note(rng, vendor, f"CN-{number}", rng.choice(prior).reference)
        elif roll < 0.42 and prior:
            doc = _payment(rng, vendor, f"PAY-{number}", rng.choice(prior))
        else:
            doc = _invoice(rng, vendor, f"INV-{number}", long=rng.random() < 0.3)
            issued.append(doc)
        tasks.append({
            "id": f"ledger-{split}-{i:03d}",
            "document": render(doc),
            "gold": {"ref": doc.reference, "lines": gold_lines(doc)},
            "meta": {"doc_type": doc.doc_type, "vendor": vendor.id, "currency": vendor.currency,
                     "lines": len(doc.lines)},
        })  # fmt: skip
    return tasks


def tasks(split: str) -> list[dict[str, Any]]:
    if split == "train":
        return generate("train", TRAIN_SEED, SIZES["train"])
    if split.startswith("live-"):
        return generate("live", int(split.removeprefix("live-")), 40)
    if split == "holdout":
        raise LookupError("the holdout is sealed; Omega decrypts it and pipes it in")
    raise LookupError(f"unknown split {split!r}")

"""The offline stand-in for Ledger's model (amendment A-23).

Until an Anthropic key is configured, the LLM metering proxy answers Ledger's
``parse_invoice`` calls with this deterministic reader instead of Claude. It reads the text
format that ``documents.py`` renders and returns the same structured-output JSON the model is
asked for. Baselines measured with it are labelled ``model=offline``: they exercise the whole
host (tools, retries, chaos, grading, telemetry) but say nothing about Claude's extraction
accuracy, which the live baseline measures once a key is added.
"""

from __future__ import annotations

import datetime as dt
import json
import re
from decimal import Decimal
from typing import Any

_MONTHS = {m: n for n, m in enumerate(
    ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"), 1)}  # fmt: skip
_SHIPPING = re.compile(r"(?i)\b(shipping|freight|delivery)\b")


def plain_amount(text: str) -> str:
    """'1.234,56' / '1 234,56' / '1,23,456.78' / '123,456' → a plain decimal string."""
    value = text.strip().replace(" ", "")
    if re.search(r",\d{2}$", value):  # comma decimals (DE, FR)
        value = value.replace(".", "").replace(",", ".")
    else:
        value = value.replace(",", "")
    return str(Decimal(value))


def iso_date(text: str) -> str:
    text = text.strip()
    if m := re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", text):
        return text
    if m := re.fullmatch(r"(\d{2})[./-](\d{2})[./-](\d{4})", text):
        return f"{m[3]}-{m[2]}-{m[1]}"
    if m := re.fullmatch(r"([A-Z][a-z]{2}) (\d{1,2}), (\d{4})", text):
        return dt.date(int(m[3]), _MONTHS[m[1]], int(m[2])).isoformat()
    raise ValueError(f"unreadable date {text!r}")


def _field(lines: list[str], label: str) -> str | None:
    for line in lines:
        if line.startswith(label + ":"):
            return line.split(":", 1)[1].strip()
    return None


def read_document(text: str) -> dict[str, Any]:
    lines = text.splitlines()
    vendor = lines[0].strip()
    if "PAYMENT RECEIPT" in text:
        doc_type, number_label = "payment", "Payment ref"
    elif "CREDIT NOTE" in text:
        doc_type, number_label = "credit_note", "Credit note no"
    else:
        doc_type, number_label = "invoice", "Invoice no"
    result: dict[str, Any] = {
        "doc_type": doc_type,
        "vendor_name": vendor,
        "reference": _field(lines, number_label) or "",
        "date": iso_date(_field(lines, "Date") or ""),
        "currency": _field(lines, "Currency") or "",
        "lines": [],
        "tax": "0",
        "total": "0",
        "applies_to": _field(lines, "Applies to invoice"),
        "amount_paid": None,
    }
    if doc_type == "payment":
        result["total"] = plain_amount(_field(lines, "Invoice total") or "0")
        result["amount_paid"] = plain_amount(_field(lines, "Amount paid") or "0")
        return result
    for line in lines:
        cells = [c.strip() for c in line.split(" | ")]
        if len(cells) == 4 and cells[0] != "Description":
            kind = "shipping" if _SHIPPING.search(cells[0]) else "item"
            result["lines"].append({"description": cells[0], "amount": plain_amount(cells[3]),
                                    "kind": kind})  # fmt: skip
        elif m := re.match(r"(MwSt\.|VAT|TVA|GST|Consumption tax) \d+%: (.+)$", line):
            result["tax"] = plain_amount(m[2])
        elif m := re.match(r"Total (due|credit): (.+)$", line):
            result["total"] = plain_amount(m[2])
    return result


def respond(request: dict[str, Any]) -> dict[str, Any]:
    """Answer a Messages API request the way ``parse_invoice`` expects (structured JSON)."""
    first = request["messages"][0]["content"]
    document = first if isinstance(first, str) else "".join(
        block.get("text", "") for block in first if isinstance(block, dict))  # fmt: skip
    return {"content": [{"type": "text", "text": json.dumps(read_document(document))}],
            "stop_reason": "end_turn"}  # fmt: skip

"""Exact journal-line match (spec §5.9.1): account, amount to the cent, currency and date.

A line posted twice is ``FAIL:DUPLICATE_ENTRY`` (the S-17 symptom); a missing line is
``FAIL:MISSING_ENTRY``; anything else that differs names the first differing field.
"""

from __future__ import annotations

from collections import Counter
from typing import Any

Key = tuple[str, int, str, str]


def _key(line: dict[str, Any]) -> Key:
    return (str(line["account"]), int(line["amount_cents"]), str(line["currency"]),
            str(line["date"]))  # fmt: skip


def grade(task: dict[str, Any], output: dict[str, Any]) -> str:
    if "error" in output:
        return f"FAIL:{output['error']}"
    posted = output.get("lines") or []
    keys = Counter(line.get("key") for line in posted)
    if any(count > 1 for count in keys.values()):
        return "FAIL:DUPLICATE_ENTRY"
    want = Counter(_key(line) for line in task["gold"]["lines"])
    got = Counter(_key(line) for line in posted)
    if got == want:
        return "PASS"
    missing, extra = want - got, got - want
    if not extra:
        return "FAIL:MISSING_ENTRY"
    if not missing:
        return "FAIL:DUPLICATE_ENTRY" if all(k in want for k in extra) else "FAIL:EXTRA_ENTRY"
    (m_account, m_cents, _, m_date), (e_account, e_cents, _, e_date) = min(missing), min(extra)
    if m_date != e_date:
        return "FAIL:WRONG_DATE"
    if {k[0] for k in missing} != {k[0] for k in extra}:
        return "FAIL:WRONG_ACCOUNT"
    return "FAIL:WRONG_AMOUNT" if m_cents != e_cents else "FAIL:MISMATCH"

