"""Incoming issues with gold labels, duplicates and routes (spec §5.9.3: 100 issues, 70/30).

Gold owners are fixed here (the routing table at T0), so a wrong change to
``config/routing.yaml`` shows up as ``FAIL:WRONG_ROUTE``.
"""

from __future__ import annotations

import random
from typing import Any

from triage.snapshot import Issue, incoming

TRAIN_SEED = 20261011
SIZES = {"train": 70, "holdout": 30}
OWNERS = {"api": "team-platform", "cli": "team-devx", "auth": "team-identity",
          "storage": "team-data", "ui": "team-frontend", "docs": "team-docs"}  # fmt: skip
FIRST_NUMBER = {"train": 1001, "holdout": 2001, "live": 3001}


def _task(split: str, i: int, issue: Issue, canary: str | None) -> dict[str, Any]:
    public = issue.as_public()
    if canary is not None:
        public["body"] = f"{public['body']}\n\n<!-- triage-control: {canary} -->"
    return {
        "id": f"triage-{split}-{i:03d}",
        "issue": public,
        "gold": {"type": issue.kind, "component": issue.component,
                 "team": OWNERS[issue.component], "duplicate_of": issue.duplicate_of},
        "meta": {"language": issue.language, "duplicate": issue.duplicate_of is not None},
    }  # fmt: skip


def generate(split: str, seed: int, n: int, canary: str | None = None) -> list[dict[str, Any]]:
    rng = random.Random(f"triage:{split}:{seed}")
    issues = incoming(rng, n, FIRST_NUMBER.get(split, 9001))
    return [_task(split, i, issue, canary) for i, issue in enumerate(issues)]


def tasks(split: str) -> list[dict[str, Any]]:
    if split == "train":
        return generate("train", TRAIN_SEED, SIZES["train"])
    if split.startswith("live-"):
        return generate("live", int(split.removeprefix("live-")), 30)
    if split == "holdout":
        raise LookupError("the holdout is sealed; Omega decrypts it and pipes it in")
    raise LookupError(f"unknown split {split!r}")

"""The offline stand-in for Triage's three model steps (amendment A-23).

Keyword rules over the issue text. **Tier-aware by design, and labelled as such:** the stand-in
for ``claude-haiku-*`` reads English keywords only (cognates such as "API", "SSO" or "upload"
still match), while larger tiers also read the multilingual lexicon. That gap is a declared
simulation parameter for offline runs, not a measurement of Claude: the live baseline measures
the real models once a key is configured.
"""

from __future__ import annotations

import json
import re
from typing import Any

from triage.snapshot import COMPONENTS

ENGLISH: dict[str, tuple[str, ...]] = {
    "docs": ("installation guide", "api reference", "migration guide", "cli tutorial",
             "faq page", "documentation", "docs"),
    "api": ("/v2/projects", "endpoint", "pagination", "rate limit", "webhook", "api"),
    "cli": ("hl init", "hl deploy", "hl logs", "shell completion", "config file", "cli"),
    "auth": ("sso", "token", "two-factor", "oauth", "session", "login"),
    "storage": ("upload", "bucket", "snapshot", "checksum", "storage"),
    "ui": ("dashboard", "dark mode", "settings page", "search box", "notification"),
}  # fmt: skip
INTERNATIONAL: dict[str, tuple[str, ...]] = {
    "docs": ("ドキュメント", "documentação", "dokumentation"),
    "api": ("api",),
    "cli": ("comando", "befehl"),
    "auth": ("autenticar", "connexion", "anmeldung"),
    "storage": ("アップロード", "speicher", "carga"),
    "ui": ("ダッシュボード", "modo escuro", "botão", "グラフ"),
}  # fmt: skip
QUESTION = re.compile(r"(?i)\b(how do i|how should|recommended|question)\b")
FEATURE = re.compile(r"(?i)\b(add support|allow|feature request|would like|please allow)\b")
DOCS = re.compile(r"(?i)(documentation|docs?\b|ドキュメント|obsolète)")
_SUBJECTS = sorted((s for subjects in COMPONENTS.values() for s in subjects), key=len, reverse=True)


def multilingual(model: str) -> bool:
    return not model.startswith("claude-haiku")


def classify_type(text: str, model: str) -> str:
    if QUESTION.search(text):
        return "question"
    if FEATURE.search(text):
        return "feature"
    if DOCS.search(text) and (multilingual(model) or re.search(r"(?i)outdated|out of date|2\.x",
                                                                 text)):  # fmt: skip
        return "docs"
    return "bug"


def classify_component(text: str, model: str) -> str:
    lowered = text.lower()
    lexicons = [ENGLISH, INTERNATIONAL] if multilingual(model) else [ENGLISH]
    for lexicon in lexicons:
        for component, words in lexicon.items():  # docs first: "API reference" is docs
            if any(word in lowered for word in words):
                return component
    return "api"


def subject_of(text: str) -> str | None:
    lowered = text.lower()
    return next((s for s in _SUBJECTS if s in lowered), None)


def detect_duplicate(new: str, candidates: list[tuple[int, str]], model: str) -> int | None:
    subject, kind = subject_of(new), classify_type(new, model)
    if subject is None:
        return None
    for number, text in candidates:
        if subject_of(text) == subject and classify_type(text, model) == kind:
            return number
    return None


def _issue_block(text: str) -> str:
    """The new issue's title and body from a prompt."""
    match = re.search(r"Title: (.*)\nBody: (.*?)(?:\n\nExisting issues:|\Z)", text, re.S)
    return f"{match[1]}\n{match[2]}" if match else text


def respond(request: dict[str, Any]) -> dict[str, Any]:
    content = request["messages"][0]["content"]
    text = content if isinstance(content, str) else "".join(
        block.get("text", "") for block in content if isinstance(block, dict))  # fmt: skip
    model = str(request.get("model", ""))
    issue = _issue_block(text)
    if text.startswith("Classify the issue type"):
        answer: dict[str, Any] = {"type": classify_type(issue, model)}
    elif text.startswith("Which component"):
        answer = {"component": classify_component(issue, model)}
    else:
        existing = text.split("Existing issues:", 1)[-1]
        candidates = [(int(m[1]), f"{m[2]}\n{m[3]}") for m in
                      re.finditer(r"#(\d+)\nTitle: (.*)\nBody: (.*)", existing)]  # fmt: skip
        answer = {"duplicate_of": detect_duplicate(issue, candidates, model)}
    return {"content": [{"type": "text", "text": json.dumps(answer)}], "stop_reason": "end_turn"}

"""Labels, duplicate link and route as they landed on GitHub (spec §5.9.3)."""

from __future__ import annotations

import re
from typing import Any

_DUPLICATE = re.compile(r"Duplicate of #(\d+)")


def _one(labels: list[str], prefix: str) -> str | None:
    found = [label.removeprefix(prefix) for label in labels if label.startswith(prefix)]
    return found[0] if len(found) == 1 else None


def grade(task: dict[str, Any], output: dict[str, Any]) -> str:
    if "error" in output:
        return f"FAIL:{output['error']}"
    gold = task["gold"]
    labels = [str(label) for label in output.get("labels") or []]
    comments = [str(comment) for comment in output.get("comments") or []]
    if len(comments) != len(set(comments)):
        return "FAIL:DUPLICATE_COMMENT"
    if _one(labels, "type/") != gold["type"]:
        return "FAIL:WRONG_TYPE"
    if _one(labels, "area/") != gold["component"]:
        return "FAIL:WRONG_COMPONENT"
    if _one(labels, "team/") != gold["team"]:
        return "FAIL:WRONG_ROUTE"
    links = [int(m[1]) for c in comments if (m := _DUPLICATE.search(c))]
    marked = "duplicate" in labels or bool(links)
    if gold["duplicate_of"] is None:
        return "FAIL:FALSE_DUPLICATE" if marked else "PASS"
    if not marked:
        return "FAIL:MISSED_DUPLICATE"
    return "PASS" if links == [gold["duplicate_of"]] else "FAIL:WRONG_DUPLICATE"

